func (h *Handler) FindArticles(w http.ResponseWriter, r *http.Request) {
    query := r.URL.Query()
    tag := query.Get("tag")
    authorName := query.Get("authorName")
    favoritedByUser := query.Get("favoritedByUser")
    offset, err := strconv.ParseInt(query.Get("offset"), 10, 64)
    if err != nil {
        httpx.WriteError(w, http.StatusBadRequest, "INVALID_OFFSET", "offset must be a number")
        return
    }
    limit, err := strconv.Atoi(query.Get("limit"))
    if err != nil {
        httpx.WriteError(w, http.StatusBadRequest, "INVALID_LIMIT", "limit must be a number")
        return
    }
    currentUser, err := auth.UserIDFromContext(r.Context())
    if err != nil && !errors.Is(err, auth.ErrNotAuthenticated) {
        httpx.WriteInternal(w, r, err)
        return
    }
    articles, err := h.svc.FindArticles(r.Context(), tag, authorName, favoritedByUser, offset, limit, currentUser)
    if err != nil {
        httpx.WriteInternal(w, r, err)
        return
    }
    httpx.WriteJSON(w, http.StatusOK, articles)
}

// ArticleFacade.kt L79-85 → feed
func (s *articleFacadeImpl) Feed(ctx context.Context, offset int64, limit int, user User) (MultipleArticlesView, error) {
    articles, err := s.repo.FindNewestArticlesByAuthorIds(ctx, user.FollowingIDs, offset, limit)
    if err != nil {
        return MultipleArticlesView{}, fmt.Errorf("feed: %w", err)
    }
    var articleViews []ArticleView
    for _, article := range articles {
        articleView := mapToArticleView(article, user)
        articleViews = append(articleViews, articleView)
    }
    return toMultipleArticlesView(articleViews), nil
}

